import { Mesh, PlaneGeometry, Group, Vector3 } from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  color,
  mix,
  uv,
  smoothstep,
  step,
  min,
  max,
  float,
  mul,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import { createTextMesh } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} textContent
 * @property {Object} visual
 * @property {Object} placement
 * @property {any[]} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} primitives
 * @property {Object} fontAtlas
 * @property {Function} textureLoader
 * @property {Function} glbLoader
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Geometry
  const width = 2.6;
  const height = 0.68;
  const geometry = new PlaneGeometry(width, height, 1, 1);

  // Gradient color nodes
  const c0 = color('#ff4450');
  const c1 = color('#ff2a38');
  const c2 = color('#c1121f');

  const gradient = mix(
    mix(c0, c1, smoothstep(0.0, 0.55, uv().y)),
    c2,
    smoothstep(0.55, 1.0, uv().y)
  );

  // Emissive edge (perimeter)
  const borderWorldWidth = 0.015;
  const borderUVWidth = borderWorldWidth / Math.max(width, height);
  const edgeDist = min(
    uv().x,
    sub(1.0, uv().x),
    uv().y,
    sub(1.0, uv().y)
  );
  const borderMask = step(edgeDist, float(borderUVWidth));
  const emissiveEdge = mul(color('#ff2a38'), float(1.6)).mul(borderMask);

  // Material
  const material = new MeshStandardNodeMaterial();
  material.colorNode = gradient;
  material.roughnessNode = float(0.5);
  material.metalnessNode = float(0.35);
  material.clearcoatNode = float(0.22);
  material.emissiveNode = emissiveEdge;

  // Mesh
  const buttonMesh = new Mesh(geometry, material);
  buttonMesh.castShadow = true;
  buttonMesh.receiveShadow = false;

  // Group container
  const root = new Group();
  root.add(buttonMesh);

  // Text – CTA label
  const labelText = config.textContent?.ctaLabel || 'BEGIN COMMISSION';
  const label = createTextMesh(labelText, {
    family: 'JetBrains Mono',
    fontSize: 20,
    fontWeight: 700,
    letterSpacing: 0.08,
    lineHeight: 1,
    color: '#e8ecf2',
    maxWidth: width - 0.5, // side padding 0.25 each side
    atlas: ctx.fontAtlas,
  });
  label.position.set(0, 0, 0.001);
  root.add(label);

  // Caption text
  const captionText = config.textContent?.caption || 'NO DEPOSIT REQUIRED';
  const caption = createTextMesh(captionText, {
    family: 'JetBrains Mono',
    fontSize: 9,
    fontWeight: 400,
    letterSpacing: 0.12,
    lineHeight: 1.4,
    color: '#e8ecf2',
    maxWidth: width,
    atlas: ctx.fontAtlas,
  });
  caption.position.set(0, -(height / 2) - 0.25, 0.001);
  root.add(caption);

  // Placement
  const pos = config.placement?.position || { x: 0, y: 0, z: 0 };
  const rot = config.placement?.rotation || { x: 0, y: 0, z: 0 };
  const scl = config.placement?.scale || { x: 1, y: 1, z: 1 };
  root.position.set(pos.x, pos.y, pos.z);
  root.rotation.set(rot.x, rot.y, rot.z);
  root.scale.set(scl.x, scl.y, scl.z);

  // Initial weighted‑settle animation
  const settleTimeline = gsap.timeline({ paused: false });
  root.scale.set(1.04, 1.04, 1.04);
  settleTimeline.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });

  // User data for handlers and cleanup
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    settleTimeline.kill();
    geometry.dispose();
    material.dispose();
    if (label && label.geometry) label.geometry.dispose();
    if (label && label.material) label.material.dispose();
    if (caption && caption.geometry) caption.geometry.dispose();
    if (caption && caption.material) caption.material.dispose();
  };

  return root;
}
